package com.smarthealth.web;import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;public class EventBus{private final CopyOnWriteArrayList<Consumer<Map<String,Object>>> listeners=new CopyOnWriteArrayList<>();public AutoCloseable subscribe(Consumer<Map<String,Object>> c){listeners.add(c);return()->listeners.remove(c);}public void publish(String type,Object data){Map<String,Object> e=Map.of("type",type,"data",data,"time",java.time.Instant.now().toString());listeners.forEach(l->{try{l.accept(e);}catch(Exception ignored){}});}}
